            ContentJson = """{"title":"Replenishment Field Reference","groups":[{"heading":"Part > Inventory cluster","items":[{"label":"Reorder Point","value":"Stock level that triggers a suggestion. Compared against available stock plus open purchase orders. When set, it overrides the burn-rate and min stock rules."},{"label":"Reorder Quantity","value":"How much each suggestion asks for. Leave blank to let Forge size the order from burn rate, lead time and safety stock days."},{"label":"Safety Stock Days","value":"Days of cushion added to the vendor lead time. Used by the burn-rate rule when no reorder point is set, and when sizing an order without a reorder quantity. Forge assumes 7 days for the trigger and 14 for sizing when blank."},{"label":"Min Stock","value":"Fallback threshold used only when the part has no reorder point and no usage history. Compared against available stock alone."},{"label":"Preferred Vendor","value":"Who the draft PO goes to when a suggestion is approved. A part with no vendor cannot be approved."}]},{"heading":"Pending Reorder Suggestions","items":[{"label":"Part # / Description","value":"The part that fell below its reorder rule."},{"label":"Vendor","value":"The vendor the draft PO will be raised to. A dash means none is set."},{"label":"Available","value":"On-hand stock minus reservations at the time of the nightly check."},{"label":"Burn/Day","value":"Average units consumed per day, from picks and shipments over the longest window (90, 60 or 30 days) that has history."},{"label":"Days Left","value":"Available plus on-order stock divided by burn per day. Red at 7 days or less, amber at 21 or less. A dash means no usage history."},{"label":"Stockout","value":"Today plus days left: the date the part is projected to reach zero."},{"label":"Suggest Qty","value":"The part's reorder quantity; otherwise burn per day times lead time plus safety stock days; otherwise the min stock amount. Always rounded up to a whole unit."},{"label":"Approve","value":"Creates a draft purchase order to the vendor for the suggested quantity and marks the suggestion approved. Price is left for you to fill in on the PO."},{"label":"Approve Selected","value":"Appears once rows are checked. Approves each selected suggestion and creates one draft PO per suggestion."},{"label":"Dismiss (X)","value":"Closes the suggestion without ordering. Opens the dismiss dialog."}]},{"heading":"Dismiss Reorder Suggestion dialog","items":[{"label":"Reason","value":"Required, up to 500 characters. Recorded on the suggestion so the decision can be reviewed later."},{"label":"Dismiss","value":"Confirms. The part is evaluated again on the next nightly run and will reappear if it is still low."}]},{"heading":"Burn Rate Analysis","items":[{"label":"Search parts","value":"Filters the list by part number or description. Press Enter to apply."},{"label":"Needs Reorder","value":"Toggle. When on, only parts currently flagged for reorder are shown."},{"label":"Refresh","value":"Reloads the list."},{"label":"Available / On Order","value":"Available stock and the total quantity on open purchase orders."},{"label":"30d / 60d / 90d per day","value":"Average consumption per day over each window. A dash means no picks or shipments in that window."},{"label":"Days Left / Stockout","value":"Same calculation as the suggestion queue, shown for every part."},{"label":"Reorder","value":"Yes when the part meets its reorder rule right now; OK otherwise."}]},{"heading":"Behind the scenes","items":[{"label":"Nightly check","value":"Runs once a day in the early morning. One pending suggestion per part; pending suggestions that no longer apply are expired automatically."},{"label":"Notification","value":"Admins and managers receive a Reorder Suggestions Ready notification whenever the check creates new suggestions."},{"label":"Consumption counted","value":"Picks and shipments only. Adjustments, transfers and scrap do not affect burn rate."}]}]}"""
