            ContentJson = """{"passingScore":80,"shuffleQuestions":false,"shuffleOptions":true,"showExplanationsAfterSubmit":true,"questions":[{"id":"q1","text":"A part has a reorder point of 25. Available stock is 10 and there are 20 on an open purchase order. Does the nightly check create a suggestion?","options":[{"id":"q1a","text":"Yes, because available stock is below 25","isCorrect":false},{"id":"q1b","text":"No, because available plus on-order stock is 30, which is above the reorder point","isCorrect":true},{"id":"q1c","text":"Only if the part also has a min stock","isCorrect":false},{"id":"q1d","text":"Only if the burn rate is above zero","isCorrect":false}],"explanation":"The reorder point is compared against available stock plus open purchase orders, so stock already on its way counts."},{"id":"q2","text":"A part has no reorder quantity set. Its burn rate is 4 per day, the vendor lead time is 10 days and safety stock days is 5. What quantity does the suggestion ask for?","options":[{"id":"q2a","text":"40","isCorrect":false},{"id":"q2b","text":"20","isCorrect":false},{"id":"q2c","text":"60","isCorrect":true},{"id":"q2d","text":"The part's min stock","isCorrect":false}],"explanation":"Without a reorder quantity, Forge sizes the order as burn per day times lead time plus safety stock days: 4 x (10 + 5) = 60."},{"id":"q3","text":"What happens when you click Approve on a reorder suggestion?","options":[{"id":"q3a","text":"The part is received into stock at the suggested quantity","isCorrect":false},{"id":"q3b","text":"A draft purchase order is created to the part's preferred vendor for the suggested quantity","isCorrect":true},{"id":"q3c","text":"An MRP run is started for the part","isCorrect":false},{"id":"q3d","text":"The part's reorder point is raised","isCorrect":false}],"explanation":"Approve writes a draft PO to the preferred vendor. You still open the PO, confirm the price and quantity, and submit it."},{"id":"q4","text":"You dismiss a suggestion for a part. What happens on the next nightly run?","options":[{"id":"q4a","text":"The part is skipped forever","isCorrect":false},{"id":"q4b","text":"The part is skipped for 30 days","isCorrect":false},{"id":"q4c","text":"The part is evaluated again and a new suggestion appears if it is still below its reorder rule","isCorrect":true},{"id":"q4d","text":"The dismissed suggestion is reopened","isCorrect":false}],"explanation":"Dismissing only closes that suggestion. The rule is re-checked every night, so a part that is still low comes back."},{"id":"q5","text":"A part shows a dash in every burn rate column on the Burn Rate Analysis list. What does that mean?","options":[{"id":"q5a","text":"The part has had no picks or shipments in the last 90 days","isCorrect":true},{"id":"q5b","text":"The part is out of stock","isCorrect":false},{"id":"q5c","text":"The part has no preferred vendor","isCorrect":false},{"id":"q5d","text":"The part is flagged for reorder","isCorrect":false}],"explanation":"Burn rate comes from picks and shipments. With none in 90 days Forge cannot size an order from usage, so give the part a reorder point and reorder quantity."}]}"""
